-- mod-atlas: fogs of map runs (screen effects). Generated by tools/clones/gen_sql.py from fogs.json and the
-- client's own Spell.dbc, the same spell rows as client_patch/patch-T.MPQ (fogs checksum a9db69cf5f590962).
-- Do not edit by hand: change tools/clones/fogs.json and regenerate both.
--
-- Each fog is an aura-260 spell (a copy of Mist of the Kvaldir, 50203, with our name, tooltip and screen
-- effect, removed on map change) that mod-atlas puts on players with the Atlas patch inside a run. The
-- ScreenEffect rows exist only in the client patch. Reserved spell IDs 90400-90449. Uninstall:
-- data/sql/uninstall/atlas_fogs_uninstall.sql.

DELETE FROM `spell_dbc` WHERE `ID` BETWEEN 90400 AND 90449;
