CREATE TABLE IF NOT EXISTS `atlas_fog` (
    `id`         INT UNSIGNED     NOT NULL,
    `theme_id`   INT UNSIGNED     NOT NULL DEFAULT 0   COMMENT '0 = any theme',
    `corruption` TINYINT UNSIGNED NOT NULL DEFAULT 255 COMMENT 'corruption level 0-5, 255 = any',
    `affix_id`   INT UNSIGNED     NOT NULL DEFAULT 0   COMMENT '> 0: an affix fog (wins over the theme)',
    `spell_id`   INT UNSIGNED     NOT NULL DEFAULT 0   COMMENT 'fog spell (spell_dbc 90400-90449)',
    `comment`    VARCHAR(100)     NOT NULL DEFAULT '',
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='mod-atlas: run fogs';

DELETE FROM `atlas_fog` WHERE `id` BETWEEN 1 AND 999;
